import java.util.ArrayList;

public class MultisetComparerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        ArrayList<Integer> a = new ArrayList<>(java.util.List.of(1, 2, 2, 3));
        ArrayList<Integer> b = new ArrayList<>(java.util.List.of(3, 2, 1, 2));
        String beforeA = a.toString();
        String beforeB = b.toString();
        try {
            check("same counts, different order", true, MultisetComparer.sameElements(a, b));
            check("list a not mutated", beforeA, a.toString());
            check("list b not mutated", beforeB, b.toString());

            ArrayList<Integer> c = new ArrayList<>(java.util.List.of(1, 2, 2));
            ArrayList<Integer> d = new ArrayList<>(java.util.List.of(1, 1, 2));
            check("same elements, different counts", false, MultisetComparer.sameElements(c, d));

            check("different sizes", false,
                    MultisetComparer.sameElements(new ArrayList<>(java.util.List.of(1, 2)),
                            new ArrayList<>(java.util.List.of(1, 2, 2))));
            check("both empty", true,
                    MultisetComparer.sameElements(new ArrayList<>(), new ArrayList<>()));
            check("one differing element", false,
                    MultisetComparer.sameElements(new ArrayList<>(java.util.List.of(1, 2, 3)),
                            new ArrayList<>(java.util.List.of(1, 2, 4))));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception: " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

