import java.util.ArrayList;
import java.util.HashMap;

public class MultisetComparer {

    public static boolean sameElements(ArrayList<Integer> a, ArrayList<Integer> b) {
        if (a.size() != b.size()) {
            return false;
        }
        HashMap<Integer, Integer> countsA = new HashMap<>();
        for (int value : a) {
            countsA.put(value, countsA.getOrDefault(value, 0) + 1);
        }
        HashMap<Integer, Integer> countsB = new HashMap<>();
        for (int value : b) {
            countsB.put(value, countsB.getOrDefault(value, 0) + 1);
        }
        return countsA.equals(countsB);
    }
}
